<!-- wp:group {"className":"sb-legal__body"} -->
<div class="wp-block-group sb-legal__body"><!-- wp:heading {"anchor":"commitment","className":"sb-legal__h"} -->
<h2 class="wp-block-heading sb-legal__h" id="commitment"><span>01</span> Our commitment</h2>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>We design and build this website to meet the Web Content Accessibility Guidelines (WCAG) 2.2 at level AA, and we check new pages against them before they go live.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"anchor":"measures","className":"sb-legal__h"} -->
<h2 class="wp-block-heading sb-legal__h" id="measures"><span>02</span> What we have done</h2>
<!-- /wp:heading -->

<!-- wp:list -->
<ul class="wp-block-list"><!-- wp:list-item -->
<li>Text and interface colours meet WCAG contrast ratios.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Every function works with a keyboard, with visible focus outlines.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Images that carry meaning have text alternatives. Decorative images are hidden from screen readers.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Pages use proper headings, landmarks and labelled form fields.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Animation is reduced when your device asks for reduced motion.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Text can be zoomed to 200% without losing content.</li>
<!-- /wp:list-item --></ul>
<!-- /wp:list -->

<!-- wp:heading {"anchor":"limits","className":"sb-legal__h"} -->
<h2 class="wp-block-heading sb-legal__h" id="limits"><span>03</span> Known limitations</h2>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Some parts of the site are provided by third parties, such as payment forms. We choose providers that take accessibility seriously, but we cannot fully control their components.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"anchor":"feedback","className":"sb-legal__h"} -->
<h2 class="wp-block-heading sb-legal__h" id="feedback"><span>04</span> Feedback and help</h2>
<!-- /wp:heading -->

<!-- wp:paragraph -->
